public static partial class ApartmentBuilder
{
    static PhoneStoryRow StoryRow(Transform parent,string name,float height,bool task=false,bool record=false)
    {
        var nav=Nav(name,parent,new Vector2(710,height),Vector2.zero,task?PhoneNavigationButton.Action.Task:record?PhoneNavigationButton.Action.Record:PhoneNavigationButton.Action.Navigate);
        if(!task&&!record)nav.GetComponent<PhoneIcon>().raycastTarget=false;
        var row=nav.gameObject.AddComponent<PhoneStoryRow>();
        row.time=Copy("Time",row.transform,"",new Vector2(440,45),new Vector2(-120,height*.5f-40),26,false,managementMuted);
        row.status=Copy("Status",row.transform,"",new Vector2(230,45),new Vector2(225,height*.5f-40),25,false,managementAccent,TextAnchor.MiddleRight);
        row.title=Copy("Title",row.transform,"",new Vector2(680,75),new Vector2(0,height*.5f-105),35,true);
        row.location=Copy("Location",row.transform,"",new Vector2(680,50),new Vector2(0,height*.5f-165),29,false,managementMuted);
        row.body=Copy("Description",row.transform,"",new Vector2(680,110),new Vector2(0,-height*.5f+60),29,false,managementMuted,TextAnchor.UpperLeft);
        if(task)row.body.gameObject.SetActive(false);if(record){row.location.gameObject.SetActive(false);row.title.rectTransform.anchoredPosition=new Vector2(0,30);}
        Divider(row.transform,-height*.5f+5);row.gameObject.SetActive(false);return row;
    }
    public static string ConnectNarrativePhone()
    {
        phoneTheme=AssetDatabase.LoadAssetAtPath<PhoneUiTheme>("Assets/Phone/Modern UI Theme.asset");var root=PrefabUtility.LoadPrefabContents(PhonePath);
        try
        {
            if(root.GetComponent<PhoneNarrativeBridge>()!=null)return "Narrative phone bridge is already installed.";
            var bridge=root.AddComponent<PhoneNarrativeBridge>();var apps=root.GetComponent<PhoneApplications>();var screen=apps.GetComponent<PhonePresentation>().screen.transform;
            var templates=PhoneRect("Narrative Row Templates",screen,new Vector2(800,1600),Vector2.zero);
            bridge.taskTemplate=StoryRow(templates,"Assignment Template",215,true);bridge.requestTemplate=StoryRow(templates,"Request Template",300);bridge.recordTemplate=StoryRow(templates,"Record Template",270,record:true);
            var tasks=apps.pages.First(p=>p.page==PhoneApplications.Page.Tasks).root.transform;var records=apps.pages.First(p=>p.page==PhoneApplications.Page.Records).root.transform;
            bridge.taskContent=tasks.GetComponentInChildren<ScrollRect>(true).content;bridge.maintenanceContent=apps.pages.First(p=>p.page==PhoneApplications.Page.Maintenance).root.GetComponentInChildren<ScrollRect>(true).content;bridge.recordsContent=records.GetComponentInChildren<ScrollRect>(true).content;
            var begin=Nav("Begin Shift",tasks,new Vector2(245,75),new Vector2(220,495),PhoneNavigationButton.Action.BeginShift);Copy("Label",begin.transform,"Begin shift",new Vector2(245,65),Vector2.zero,28,true,managementAccent,TextAnchor.MiddleCenter);bridge.beginButton=begin.gameObject;begin.gameObject.SetActive(false);
            var report=Nav("Submit Report",records,new Vector2(270,75),new Vector2(210,495),PhoneNavigationButton.Action.ShowReport);Copy("Label",report.transform,"Submit report",new Vector2(265,65),Vector2.zero,28,true,managementAccent,TextAnchor.MiddleCenter);bridge.reportButton=report.gameObject;report.gameObject.SetActive(false);
            var form=PhoneRect("Nightly Report Form",records,new Vector2(720,940),new Vector2(0,-35));var background=PhoneImage("Form Background",form,new Vector2(720,940),Vector2.zero,phoneTheme.background);background.raycastTarget=true;
            Copy("Help",form,"Summarize your patrol and any incidents.",new Vector2(680,100),new Vector2(0,380),32,false,managementMuted);bridge.reportInput=Entry("Shift Report",form,new Vector2(680,520),new Vector2(0,30),"Patrol, faults, and observations…",true);bridge.reportInput.characterLimit=1800;
            var submit=Nav("Send Report",form,new Vector2(680,85),new Vector2(0,-335),PhoneNavigationButton.Action.SubmitReport,PhoneApplications.Page.Home,phoneTheme.surface);Copy("Label",submit.transform,"Submit nightly report",new Vector2(650,75),Vector2.zero,32,true,null,TextAnchor.MiddleCenter);
            var cancel=Nav("Cancel Report",form,new Vector2(680,75),new Vector2(0,-430),PhoneNavigationButton.Action.CancelReport);Copy("Label",cancel.transform,"Back to records",new Vector2(650,65),Vector2.zero,29,false,managementMuted,TextAnchor.MiddleCenter);bridge.reportForm=form.gameObject;form.gameObject.SetActive(false);
            var chat=apps.pages.First(p=>p.page==PhoneApplications.Page.Conversation).root.transform;
            bridge.legacyMessages=chat.Cast<Transform>().Where(t=>new[]{"Date Pill","Date Separator","Incoming Bubble","Incoming Message","Incoming Time","Outgoing Bubble","Outgoing Message","Outgoing Time","Local Draft"}.Contains(t.name)).Select(t=>t.gameObject).ToArray();
            var messages=ScrollArea(chat,"Scripted Messages",920);((RectTransform)messages.parent).sizeDelta=new Vector2(720,920);((RectTransform)messages.parent).anchoredPosition=new Vector2(0,-10);bridge.messageContent=messages;bridge.messageScroll=messages.parent.gameObject;bridge.messageScroll.SetActive(false);
            for(int i=0;i<2;i++){var bubble=Shape(i==0?"Incoming Template":"Outgoing Template",templates,new Vector2(570,200),Vector2.zero,i==0?phoneTheme.surface:new Color(.075f,.28f,.24f));Copy("Body",bubble.transform,"",new Vector2(510,145),new Vector2(0,12),33,false,null,TextAnchor.UpperLeft);Copy("Time",bubble.transform,"",new Vector2(510,36),new Vector2(0,-75),22,false,managementMuted,TextAnchor.MiddleRight);bubble.gameObject.SetActive(false);if(i==0)bridge.incomingTemplate=bubble.gameObject;else bridge.outgoingTemplate=bubble.gameObject;}
            var date=PhoneRect("Message Date Template",templates,new Vector2(680,55),Vector2.zero);Copy("Date",date,"",new Vector2(650,50),Vector2.zero,24,false,managementMuted,TextAnchor.MiddleCenter);date.gameObject.SetActive(false);bridge.dateTemplate=date.gameObject;
            var chats=apps.whatsApp.transform;var rows=chats.GetComponentsInChildren<PhoneNavigationButton>(true).Where(n=>n.action==PhoneNavigationButton.Action.Conversation).OrderBy(n=>n.index).ToArray();bridge.contactNames=new Text[rows.Length];bridge.contactPreviews=new Text[rows.Length];bridge.contactTimes=new Text[rows.Length];bridge.unreadBadges=new GameObject[rows.Length];bridge.unreadCounts=new Text[rows.Length];
            for(int i=0;i<rows.Length;i++){var row=rows[i].transform;bridge.contactNames[i]=row.Find("Contact").GetComponent<Text>();bridge.contactPreviews[i]=row.Find("Preview").GetComponent<Text>();bridge.contactTimes[i]=row.Find("Time").GetComponent<Text>();var badge=row.Find("Unread");if(badge==null)badge=Shape("Unread",row,new Vector2(34,34),new Vector2(311,-27),phoneTheme.accent,PhoneIcon.Symbol.RoundedRect,.5f).transform;var count=row.Find("Count");if(count==null)count=Copy("Count",badge,"1",new Vector2(30,32),Vector2.zero,23,true,phoneTheme.background,TextAnchor.MiddleCenter).transform;else count.SetParent(badge,true);bridge.unreadBadges[i]=badge.gameObject;bridge.unreadCounts[i]=count.GetComponent<Text>();}
            foreach(string name in new[]{"System Chrome","Flashlight Glance Screen","System Dialog"})screen.Find(name).SetAsLastSibling();
            PrefabUtility.SaveAsPrefabAsset(root,PhonePath);AssetDatabase.SaveAssets();return "Phone connected to story tasks, service requests, records, landlord/supervisor messages and report form. Existing home and app styling retained.";
        }
        finally{PrefabUtility.UnloadPrefabContents(root);}
    }
    static void StoryButton(Transform parent,string name,string label,Vector2 at,UnityEngine.Events.UnityAction action)
    {var button=PhoneButton(name,parent,label,new Vector2(390,80),at,new Color(.12f,.14f,.15f),30);UnityEventTools.AddPersistentListener(button.onClick,action);}
    public static string BuildStoryPresentation()
    {
        phoneTheme=AssetDatabase.LoadAssetAtPath<PhoneUiTheme>("Assets/Phone/Modern UI Theme.asset");var root=new GameObject("Story Director");var director=root.AddComponent<StoryDirector>();director.definition=AssetDatabase.LoadAssetAtPath<NightDefinition>(StoryResources+"Night 1.asset");
