        var modal=PhoneRect("Document and Report",canvas,new Vector2(1920,1080),Vector2.zero);var scrim=PhoneImage("Scrim",modal,new Vector2(1920,1080),Vector2.zero,new Color(.018f,.022f,.025f,.97f));scrim.raycastTarget=true;ui.modal=modal.gameObject;ui.documentTitle=Copy("Document Title",modal,"",new Vector2(1150,100),new Vector2(0,430),40,true);
        var viewport=PhoneRect("Document Viewport",modal,new Vector2(1120,620),new Vector2(0,30));var rectImage=viewport.gameObject.AddComponent<Image>();rectImage.color=Color.clear;viewport.gameObject.AddComponent<RectMask2D>();var content=PhoneRect("Document Content",viewport,new Vector2(1100,620),Vector2.zero);content.anchorMin=content.anchorMax=content.pivot=new Vector2(.5f,1);ui.documentContent=content;ui.documentBody=Copy("Document Text",content,"",new Vector2(1080,620),Vector2.zero,29,false,new Color(.82f,.83f,.81f),TextAnchor.UpperLeft);ui.documentBody.rectTransform.anchorMin=ui.documentBody.rectTransform.anchorMax=ui.documentBody.rectTransform.pivot=new Vector2(.5f,1);ui.documentScroll=viewport.gameObject.AddComponent<ScrollRect>();ui.documentScroll.viewport=viewport;ui.documentScroll.content=content;ui.documentScroll.horizontal=false;ui.documentScroll.scrollSensitivity=45;
